135:   ObjectNode.prototype._toTex = function(options) {
136:     var entries = [];
137:     for (var key in this.properties) {
138:       if (this.properties.hasOwnProperty(key)) {
139:         entries.push("\\mathbf{" + key + ':} & ' + this.properties[key].toTex(options) + "\\\\");
140:       }
141:     }
142:     return '\\left\\{\\begin{array}{ll}' + entries.join('\n') + '\\end{array}\\right\\}';
